insert into public.solutions (id, slug, title, eyebrow, summary, short, icon, tone, badge, stats, points, video, sort_order) values ('sol-revenue', 'revenue-automation', 'Revenue Automation', 'Solution · +45% AOV', 'AI-optimized pricing, upsells and abandoned cart recovery running around the clock, so every visitor sees the offer most likely to convert them.', 'Pricing, upsells and cart recovery — 24/7.', 'revenue', '#3B82F6', '+45% AOV', '[["Avg order value", "+45%"], ["Carts recovered", "1 in 3"], ["Setup time", "7–14 days"]]'::jsonb, '["Dynamic upsell and bundle logic based on cart contents", "Cart recovery sequences over email, SMS and WhatsApp", "Post-purchase offers triggered automatically", "Price testing that reports back what actually converts"]'::jsonb, '{}'::jsonb, '0') on conflict (id) do nothing;
